
/*
 * ============================================================
 * Project Name : SFIP (Startup Failure Intelligence Platform)
 * File Name    : ChatMessageService.java
 * Package      : com.sfip.backend.service
 * File Path    : src/main/java/com/sfip/backend/service/ChatMessageService.java
 *
 * Purpose:
 * Handles business logic for chat messages.
 *
 * Responsibilities:
 * 1. Saves user messages.
 * 2. Saves assistant messages generated by the backend.
 * 3. Retrieves chat history for a startup session.
 * 4. Verifies session ownership.
 * 5. Maintains transactional consistency.
 *
 * ============================================================
 */

package com.sfip.backend.service;

import com.sfip.backend.entity.ChatMessage;
import com.sfip.backend.entity.MessageRole;
import com.sfip.backend.entity.StartupSession;
import com.sfip.backend.repository.ChatMessageRepository;

import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.util.List;

@Service
@Transactional(readOnly = true)
public class ChatMessageService {

    private final ChatMessageRepository chatMessageRepository;
    private final StartupSessionService startupSessionService;

    private static final int MAX_MESSAGE_LENGTH = 20000;

    // --------------------------------------------------------
    // Constructor injection.
    // --------------------------------------------------------

    public ChatMessageService(
            ChatMessageRepository chatMessageRepository,
            StartupSessionService startupSessionService) {

        this.chatMessageRepository = chatMessageRepository;
        this.startupSessionService = startupSessionService;
    }

    // --------------------------------------------------------
    // Save a user message.
    // --------------------------------------------------------

    @Transactional
    public ChatMessage saveUserMessage(
            Long sessionId,
            Long userId,
            String content) {

        StartupSession session =
                getOwnedSession(sessionId, userId);

        validateContent(content);

        ChatMessage message = new ChatMessage(
                session,
                MessageRole.USER,
                content.trim()
        );

        return chatMessageRepository.save(message);
    }

    // --------------------------------------------------------
    // Save an assistant message.
    //
    // IMPORTANT:
    // Call this only from trusted backend AI processing logic.
    // Do not expose this method through a client-facing API
    // that allows users to submit arbitrary assistant messages.
    // --------------------------------------------------------

    @Transactional
    public ChatMessage saveAssistantMessage(
            Long sessionId,
            Long userId,
            String content) {

        StartupSession session =
                getOwnedSession(sessionId, userId);

        validateContent(content);

        ChatMessage message = new ChatMessage(
                session,
                MessageRole.ASSISTANT,
                content.trim()
        );

        return chatMessageRepository.save(message);
    }

    // --------------------------------------------------------
    // Retrieve chat history for a user's session.
    //
    // Messages are returned in chronological order.
    // --------------------------------------------------------

    public List<ChatMessage> getChatHistory(
            Long sessionId,
            Long userId) {

        // Verify ownership before retrieving messages.
        getOwnedSession(sessionId, userId);

        return chatMessageRepository
                .findAllBySession_IdOrderByCreatedAtAscIdAsc(
                        sessionId
                );
    }

    // --------------------------------------------------------
    // Verify that the session belongs to the given user.
    // --------------------------------------------------------

    private StartupSession getOwnedSession(
            Long sessionId,
            Long userId) {

        if (sessionId == null || sessionId <= 0) {
            throw new IllegalArgumentException(
                    "Valid session ID is required."
            );
        }

        if (userId == null || userId <= 0) {
            throw new IllegalArgumentException(
                    "Valid user ID is required."
            );
        }

        return startupSessionService
                .getUserSession(sessionId, userId)
                .orElseThrow(() ->
                        new IllegalArgumentException(
                                "Analysis session not found."
                        )
                );
    }

    // --------------------------------------------------------
    // Validate message content.
    // --------------------------------------------------------

    private void validateContent(String content) {

        if (content == null || content.isBlank()) {
            throw new IllegalArgumentException(
                    "Message content cannot be empty."
            );
        }

        String normalizedContent = content.trim();

        if (normalizedContent.length() > MAX_MESSAGE_LENGTH) {
            throw new IllegalArgumentException(
                    "Message cannot exceed "
                            + MAX_MESSAGE_LENGTH
                            + " characters."
            );
        }
    }
}
